    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $c2 = 0; $c5 = 0;
        $factors = [];
        for ($i = $left; $i <= $right; $i++) {
            $x = $i;
            while ($x % 2 == 0) { $x = intdiv($x, 2); $c2++; }
            while ($x % 5 == 0) { $x = intdiv($x, 5); $c5++; }
            $factors[] = $x;
        }
        $C = min($c2, $c5);
        $c2 -= $C; $c5 -= $C;
        for ($k = 0; $k < $c2; $k++) $factors[] = 2;
        for ($k = 0; $k < $c5; $k++) $factors[] = 5;

        $LIM = 10000000000;
        $exact = 1;
        $big = false;
        $pref = 1.0;
        $suf = 1;
        foreach ($factors as $f) {
            if (!$big) {
                $exact *= $f;
                if ($exact >= $LIM) {
                    $big = true;
                }
            }
            $pref *= $f;
            while ($pref >= 10.0) {
                $pref /= 10.0;
