            $suf = ($suf * $f) % 100000;
        }
        if (!$big) {
            return $exact . "e" . $C;
        }
        $prefix = (int)floor($pref * 10000);
        if ($prefix >= 100000) $prefix = 99999;
        if ($prefix < 10000) $prefix = 10000;
        return sprintf("%d...%05de%d", $prefix, $suf, $C);
    }
}
