class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $digits = substr($s, 1, strlen($s) - 2);
        $n = strlen($digits);
        $result = [];
        for ($i = 1; $i < $n; $i++) {
            $left = $this->generate(substr($digits, 0, $i));
            if (empty($left)) continue;
            $right = $this->generate(substr($digits, $i));
            if (empty($right)) continue;
            foreach ($left as $l) {
                foreach ($right as $r) {
                    $result[] = "(" . $l . ", " . $r . ")";
                }
            }
        }
        return $result;
    }

    private function generate($str) {
        $res = [];
        $n = strlen($str);
        if ($n == 0) return $res;
        // integer form
        if ($n == 1 || $str[0] != '0') {
            $res[] = $str;
        }
        // decimal forms
        for ($i = 1; $i < $n; $i++) {
            $intPart = substr($str, 0, $i);
            $fracPart = substr($str, $i);
            if ($i > 1 && $intPart[0] == '0') continue;
            if ($fracPart[strlen($fracPart) - 1] == '0') continue;
            $res[] = $intPart . "." . $fracPart;
        }
        return $res;
    }
}
