class Solution {

    /**
     * @param Integer $n
     * @return Integer
     */
    function countVowelPermutation($n) {
        $mod = 1000000007;
        $a = 1; $e = 1; $i = 1; $o = 1; $u = 1;
        for ($k = 2; $k <= $n; $k++) {
            $na = ($e + $i + $u) % $mod;
            $ne = ($a + $i) % $mod;
            $ni = ($e + $o) % $mod;
            $no = $i % $mod;
            $nu = ($i + $o) % $mod;
            $a = $na; $e = $ne; $i = $ni; $o = $no; $u = $nu;
        }
        return ($a + $e + $i + $o + $u) % $mod;
    }
}
```

