    function numSmallerByFrequency($queries, $words) {
        $f = function($s) {
            $n = strlen($s);
            $min = null;
            $cnt = 0;
            for ($i = 0; $i < $n; $i++) {
                $c = $s[$i];
                if ($min === null || $c < $min) {
                    $min = $c;
                    $cnt = 1;
                } elseif ($c === $min) {
                    $cnt++;
                }
            }
            return $cnt;
