class Solution {

    /**
     * @param Integer[] $stones
     * @return Boolean
     */
    function canCross($stones) {
        $n = count($stones);
        if ($n < 2) return true;
        if ($stones[1] != 1) return false;
        // Early check: gaps can't exceed index (max jump at stone i is i)
        for ($i = 1; $i < $n; $i++) {
            if ($stones[$i] - $stones[$i - 1] > $i) return false;
        }
        $pos = [];
        foreach ($stones as $i => $s) {
            $pos[$s] = $i;
        }
        // dp[i] = set of jump sizes that can reach stone i
        $dp = array_fill(0, $n, []);
        $dp[0][0] = true;
        for ($i = 0; $i < $n; $i++) {
            foreach ($dp[$i] as $k => $_) {
                for ($d = $k - 1; $d <= $k + 1; $d++) {
                    if ($d <= 0) continue;
                    $target = $stones[$i] + $d;
                    if (isset($pos[$target])) {
                        $j = $pos[$target];
                        if ($j == $n - 1) return true;
                        $dp[$j][$d] = true;
                    }
                }
            }
        }
        return !empty($dp[$n - 1]);
    }
}
