class Solution {

    /**
     * @param String $directions
     * @return Integer
     */
    function countCollisions($directions) {
        $s = trim($directions);
        $n = strlen($s);
        $l = 0;
        while ($l < $n && $s[$l] === 'L') {
            $l++;
        }
        $r = $n - 1;
        while ($r >= $l && $s[$r] === 'R') {
            $r--;
