class Solution {

    /**
     * @param Integer[][] $points
     * @return Integer
     */
    function maxPoints($points) {
        $n = count($points);
        if ($n <= 2) {
            return $n;
        }
        $best = 1;
        for ($i = 0; $i < $n; $i++) {
            $counts = [];
            $localMax = 0;
            for ($j = $i + 1; $j < $n; $j++) {
                $dx = $points[$j][0] - $points[$i][0];
                $dy = $points[$j][1] - $points[$i][1];
                if ($dx == 0) {
                    $dy = 1;
                } elseif ($dy == 0) {
                    $dx = 1;
                } else {
                    $g = $this->gcd(abs($dx), abs($dy));
                    $dx = intdiv($dx, $g);
                    $dy = intdiv($dy, $g);
                    if ($dx < 0) {
                        $dx = -$dx;
                        $dy = -$dy;
                    }
                }
                $key = $dx . ',' . $dy;
                if (!isset($counts[$key])) {
                    $counts[$key] = 0;
                }
                $counts[$key]++;
                if ($counts[$key] > $localMax) {
                    $localMax = $counts[$key];
                }
            }
            if ($localMax + 1 > $best) {
                $best = $localMax + 1;
            }
        }
        return $best;
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a;
    }
}
