class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxScore($nums) {
        $m = count($nums);
        $g = array_fill(0, $m, array_fill(0, $m, 0));
        for ($i = 0; $i < $m; $i++) {
            for ($j = $i + 1; $j < $m; $j++) {
                $a = $nums[$i]; $b = $nums[$j];
                while ($b != 0) { $t = $a % $b; $a = $b; $b = $t; }
                $g[$i][$j] = $a;
                $g[$j][$i] = $a;
            }
        }
        $full = (1 << $m) - 1;
        $dp = array_fill(0, 1 << $m, -1);
        $dp[0] = 0;
        $pc = array_fill(0, 1 << $m, 0);
        for ($mask = 1; $mask <= $full; $mask++) {
            $pc[$mask] = $pc[$mask >> 1] + ($mask & 1);
        }
        for ($mask = 0; $mask <= $full; $mask++) {
            if ($dp[$mask] < 0) continue;
            if ($pc[$mask] & 1) continue;
            $op = ($pc[$mask] >> 1) + 1;
            $cur = $dp[$mask];
            for ($i = 0; $i < $m; $i++) {
                if ($mask & (1 << $i)) continue;
                for ($j = $i + 1; $j < $m; $j++) {
                    if ($mask & (1 << $j)) continue;
                    $nm = $mask | (1 << $i) | (1 << $j);
                    $val = $cur + $op * $g[$i][$j];
                    if ($val > $dp[$nm]) $dp[$nm] = $val;
                }
            }
        }
        return $dp[$full];
    }
}
