class CustomStack {
    private $maxSize;
    private $stack;
    private $inc;
    private $size;

    /**
     * @param Integer $maxSize
     */
    function __construct($maxSize) {
        $this->maxSize = $maxSize;
        $this->stack = array_fill(0, $maxSize, 0);
        $this->inc = array_fill(0, $maxSize, 0);
        $this->size = 0;
    }

    /**
     * @param Integer $x
     * @return NULL
     */
    function push($x) {
        if ($this->size < $this->maxSize) {
            $this->stack[$this->size] = $x;
            $this->inc[$this->size] = 0;
            $this->size++;
        }
    }

    /**
     * @return Integer
     */
    function pop() {
        if ($this->size == 0) {
            return -1;
