class Solution {

    /**
     * @param Integer[][] $grid
     * @return Integer
     */
    function largestMagicSquare($grid) {
        $m = count($grid);
        $n = count($grid[0]);
        // rowPre[i][j] = sum of grid[i][0..j-1]
        $rowPre = array_fill(0, $m, array_fill(0, $n + 1, 0));
        // colPre[j][i] = sum of grid[0..i-1][j]
        $colPre = array_fill(0, $n, array_fill(0, $m + 1, 0));
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $rowPre[$i][$j + 1] = $rowPre[$i][$j] + $grid[$i][$j];
                $colPre[$j][$i + 1] = $colPre[$j][$i] + $grid[$i][$j];
            }
        }
        $maxK = min($m, $n);
        for ($k = $maxK; $k >= 2; $k--) {
            for ($r = 0; $r + $k <= $m; $r++) {
                for ($c = 0; $c + $k <= $n; $c++) {
                    if ($this->check($grid, $rowPre, $colPre, $r, $c, $k)) {
                        return $k;
                    }
                }
            }
        }
        return 1;
    }

    private function check($grid, $rowPre, $colPre, $r, $c, $k) {
        $target = $rowPre[$r][$c + $k] - $rowPre[$r][$c];
        for ($i = $r; $i < $r + $k; $i++) {
            if ($rowPre[$i][$c + $k] - $rowPre[$i][$c] != $target) return false;
        }
        for ($j = $c; $j < $c + $k; $j++) {
            if ($colPre[$j][$r + $k] - $colPre[$j][$r] != $target) return false;
        }
        $d1 = 0;
        $d2 = 0;
        for ($t = 0; $t < $k; $t++) {
            $d1 += $grid[$r + $t][$c + $t];
            $d2 += $grid[$r + $t][$c + $k - 1 - $t];
        }
        return $d1 == $target && $d2 == $target;
    }
