```php
class Solution {

    /**
     * @param Integer $maxTime
     * @param Integer[][] $edges
     * @param Integer[] $passingFees
     * @return Integer
     */
    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $INF = PHP_INT_MAX >> 1;
        // dp[t] = array of min cost to reach node v with exactly t time
        $dp = array();
        $dp[0] = array_fill(0, $n, $INF);
        $dp[0][0] = $passingFees[0];
        $best = $INF;
        for ($t = 1; $t <= $maxTime; $t++) {
            $cur = array_fill(0, $n, $INF);
            foreach ($edges as $e) {
                $u = $e[0]; $v = $e[1]; $w = $e[2];
                if ($w > $t) continue;
                $prev = $dp[$t - $w];
                if ($prev[$u] < $INF) {
                    $c = $prev[$u] + $passingFees[$v];
                    if ($c < $cur[$v]) $cur[$v] = $c;
                }
                if ($prev[$v] < $INF) {
                    $c = $prev[$v] + $passingFees[$u];
                    if ($c < $cur[$u]) $cur[$u] = $c;
                }
            }
            $dp[$t] = $cur;
            if ($cur[$n - 1] < $best) $best = $cur[$n - 1];
        }
        if ($dp[0][$n - 1] < $best) $best = $dp[0][$n - 1];
        return $best >= $INF ? -1 : $best;
    }
}
