        $prefix = array_fill(0, $n + 1, 0);
        for ($i = 0; $i < $n; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $nums[$i];
        }
        return max(
            $this->helper($prefix, $n, $firstLen, $secondLen),
            $this->helper($prefix, $n, $secondLen, $firstLen)
