Classic approach: recursively split into left/right subtrees, multiply C(left+right, left) with counts of subtrees, using Pascal's triangle for binomials mod 1e9+7. Subtract 1 at the end.

```php
class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function numOfWays($nums) {
        $MOD = 1000000007;
        $n = count($nums);
        // Pascal's triangle
        $C = array();
        for ($i = 0; $i <= $n; $i++) {
            $C[$i] = array_fill(0, $i + 1, 0);
            $C[$i][0] = 1;
            $C[$i][$i] = 1;
            for ($j = 1; $j < $i; $j++) {
                $C[$i][$j] = ($C[$i - 1][$j - 1] + $C[$i - 1][$j]) % $MOD;
            }
        }
        $res = $this->solve($nums, $C, $MOD);
        return ($res - 1 + $MOD) % $MOD;
    }

    private function solve($arr, &$C, $MOD) {
        $m = count($arr);
        if ($m <= 2) {
            return 1;
        }
        $root = $arr[0];
        $left = array();
        $right = array();
        for ($i = 1; $i < $m; $i++) {
            if ($arr[$i] < $root) {
                $left[] = $arr[$i];
            } else {
                $right[] = $arr[$i];
            }
        }
        $l = count($left);
        $r = count($right);
        $ways = $C[$l + $r][$l];
        $lw = $this->solve($left, $C, $MOD);
        $rw = $this->solve($right, $C, $MOD);
        $res = ($ways * $lw) % $MOD;
        $res = ($res * $rw) % $MOD;
        return $res;
    }
}
