class Solution {

    /**
     * @param String $s
     * @return Integer
     */
    function minSwaps($s) {
        $n = strlen($s);
        $bal = 0;
        $maxNeg = 0;
        for ($i = 0; $i < $n; $i++) {
            if ($s[$i] === '[') {
                $bal++;
            } else {
                $bal--;
                if ($bal < $maxNeg) {
                    $maxNeg = $bal;
                }
            }
        }
        $imb = -$maxNeg;
        return intdiv($imb + 1, 2);
    }
}
