Union-Find approach: for each request, find roots of u and v; if same, success. Otherwise, check every restriction — if one restriction's endpoints map to roots {ru, rv}, reject; else union.

```php
class Solution {

    /**
     * @param Integer $n
     * @param Integer[][] $restrictions
     * @param Integer[][] $requests
     * @return Boolean[]
     */
    function friendRequests($n, $restrictions, $requests) {
        $parent = range(0, $n - 1);
        $find = function($x) use (&$parent, &$find) {
            while ($parent[$x] !== $x) {
                $parent[$x] = $parent[$parent[$x]];
                $x = $parent[$x];
            }
            return $x;
        };
        $result = [];
        foreach ($requests as $req) {
            $u = $req[0];
            $v = $req[1];
            $ru = $find($u);
            $rv = $find($v);
            if ($ru === $rv) {
                $result[] = true;
                continue;
            }
            $ok = true;
            foreach ($restrictions as $r) {
                $rx = $find($r[0]);
                $ry = $find($r[1]);
                if (($rx === $ru && $ry === $rv) || ($rx === $rv && $ry === $ru)) {
                    $ok = false;
                    break;
                }
            }
            if ($ok) {
                $parent[$ru] = $rv;
            }
            $result[] = $ok;
        }
        return $result;
    }
}
