class Solution {

    /**
     * @param String $s
     * @param String $p
     * @return Boolean
     */
    function isMatch($s, $p) {
        $n = strlen($s);
        $m = strlen($p);
        $dp = array_fill(0, $n + 1, array_fill(0, $m + 1, false));
        $dp[0][0] = true;

        for ($j = 2; $j <= $m; $j++) {
            if ($p[$j - 1] === '*') {
                $dp[0][$j] = $dp[0][$j - 2];
            }
        }

        for ($i = 1; $i <= $n; $i++) {
            for ($j = 1; $j <= $m; $j++) {
                $pc = $p[$j - 1];
                if ($pc === '*') {
                    $prev = $p[$j - 2];
                    // zero occurrences
                    $dp[$i][$j] = $dp[$i][$j - 2];
                    // one or more occurrences
                    if (!$dp[$i][$j] && ($prev === '.' || $prev === $s[$i - 1])) {
                        $dp[$i][$j] = $dp[$i - 1][$j];
                    }
                } else {
                    if ($pc === '.' || $pc === $s[$i - 1]) {
                        $dp[$i][$j] = $dp[$i - 1][$j - 1];
                    }
                }
            }
        }

        return $dp[$n][$m];
    }
}
