class Solution {

    /**
     * @param Integer $n
     * @return Integer
     */
    function nextBeautifulNumber($n) {
        $x = $n + 1;
        while (true) {
            if ($this->isBalanced($x)) {
                return $x;
            }
            $x++;
        }
    }

    private function isBalanced($x) {
        $cnt = array_fill(0, 10, 0);
        $y = $x;
        while ($y > 0) {
            $d = $y % 10;
            if ($d == 0) return false;
            $cnt[$d]++;
            $y = intdiv($y, 10);
        }
        for ($d = 1; $d <= 9; $d++) {
            if ($cnt[$d] != 0 && $cnt[$d] != $d) {
                return false;
            }
        }
        return true;
    }
}
