```php
class Solution {

    /**
     * @param String $s1
     * @param String $s2
     * @return Boolean
     */
    function isScramble($s1, $s2) {
        $n = strlen($s1);
        if ($n !== strlen($s2)) return false;
        $memo = [];
        return $this->solve($s1, $s2, 0, 0, $n, $memo);
    }

    private function solve($s1, $s2, $i, $j, $len, &$memo) {
        $key = $i . ',' . $j . ',' . $len;
        if (isset($memo[$key])) return $memo[$key];
        if (substr($s1, $i, $len) === substr($s2, $j, $len)) {
            return $memo[$key] = true;
        }
        $cnt = array_fill(0, 26, 0);
        for ($k = 0; $k < $len; $k++) {
            $cnt[ord($s1[$i + $k]) - 97]++;
            $cnt[ord($s2[$j + $k]) - 97]--;
        }
        for ($c = 0; $c < 26; $c++) {
            if ($cnt[$c] !== 0) return $memo[$key] = false;
        }
        for ($k = 1; $k < $len; $k++) {
            if ($this->solve($s1, $s2, $i, $j, $k, $memo) &&
                $this->solve($s1, $s2, $i + $k, $j + $k, $len - $k, $memo)) {
                return $memo[$key] = true;
            }
            if ($this->solve($s1, $s2, $i, $j + $len - $k, $k, $memo) &&
                $this->solve($s1, $s2, $i + $k, $j, $len - $k, $memo)) {
                return $memo[$key] = true;
            }
        }
        return $memo[$key] = false;
    }
}
