class Solution {

    /**
     * @param Integer[] $nums1
     * @param Integer[] $nums2
     * @return Integer
     */
    function numTriplets($nums1, $nums2) {
        return $this->countType($nums1, $nums2) + $this->countType($nums2, $nums1);
    }

    private function countType($src, $other) {
        $freq = [];
        foreach ($other as $v) {
            if (!isset($freq[$v])) {
                $freq[$v] = 0;
            }
            $freq[$v]++;
        }
        $total = 0;
        $cache = [];
        foreach ($src as $x) {
            if (isset($cache[$x])) {
                $total += $cache[$x];
                continue;
            }
            $target = $x * $x;
            $count = 0;
            foreach ($freq as $a => $ca) {
                if ($target % $a !== 0) {
                    continue;
                }
                $b = intdiv($target, $a);
                if ($a > $b) {
                    continue;
                }
                if ($a === $b) {
                    $count += intdiv($ca * ($ca - 1), 2);
                } elseif (isset($freq[$b])) {
                    $count += $ca * $freq[$b];
