class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function canPartitionKSubsets($nums, $k) {
        $total = array_sum($nums);
        if ($total % $k != 0) return false;
        $target = intdiv($total, $k);
        rsort($nums);
        if ($nums[0] > $target) return false;
        $n = count($nums);
        $buckets = array_fill(0, $k, 0);
        return $this->dfs($nums, $n, 0, $buckets, $k, $target);
    }

    private function dfs($nums, $n, $idx, &$buckets, $k, $target) {
        if ($idx == $n) return true;
        $val = $nums[$idx];
        for ($i = 0; $i < $k; $i++) {
            if ($buckets[$i] + $val <= $target) {
                $buckets[$i] += $val;
                if ($this->dfs($nums, $n, $idx + 1, $buckets, $k, $target)) return true;
                $buckets[$i] -= $val;
            }
            if ($buckets[$i] == 0) break;
        }
        return false;
    }
}
