class Solution {

    /**
     * @param String[] $stickers
     * @param String $target
     * @return Integer
     */
    function minStickers($stickers, $target) {
        $n = strlen($target);
        $full = (1 << $n) - 1;
        $m = count($stickers);
        $counts = [];
        foreach ($stickers as $s) {
            $c = array_fill(0, 26, 0);
            $len = strlen($s);
            for ($i = 0; $i < $len; $i++) {
                $c[ord($s[$i]) - 97]++;
            }
            $counts[] = $c;
        }
        $tchars = [];
        for ($i = 0; $i < $n; $i++) {
            $tchars[$i] = ord($target[$i]) - 97;
        }
        $INF = PHP_INT_MAX;
        $dp = array_fill(0, $full + 1, $INF);
        $dp[0] = 0;
        for ($mask = 0; $mask <= $full; $mask++) {
            if ($dp[$mask] === $INF) continue;
            $cur = $dp[$mask];
            for ($j = 0; $j < $m; $j++) {
                $c = $counts[$j];
                $newMask = $mask;
                for ($i = 0; $i < $n; $i++) {
                    if (($mask >> $i) & 1) continue;
                    $ch = $tchars[$i];
                    if ($c[$ch] > 0) {
                        $c[$ch]--;
                        $newMask |= (1 << $i);
                    }
                }
                if ($newMask !== $mask && $dp[$newMask] > $cur + 1) {
                    $dp[$newMask] = $cur + 1;
                }
            }
        }
        return $dp[$full] === $INF ? -1 : $dp[$full];
    }
}
