class Solution {

    /**
     * @param String $s
     * @param String $p
     * @return Boolean
     */
    function isMatch($s, $p) {
        $n = strlen($s);
        $m = strlen($p);
        $i = 0;
        $j = 0;
        $starIdx = -1;
        $matchIdx = 0;

        while ($i < $n) {
            if ($j < $m && ($p[$j] == '?' || $p[$j] == $s[$i])) {
                $i++;
                $j++;
            } elseif ($j < $m && $p[$j] == '*') {
                $starIdx = $j;
                $matchIdx = $i;
                $j++;
            } elseif ($starIdx != -1) {
                $j = $starIdx + 1;
                $matchIdx++;
                $i = $matchIdx;
            } else {
                return false;
            }
        }

        while ($j < $m && $p[$j] == '*') {
            $j++;
        }

        return $j == $m;
    }
}
