class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $leftChild
     * @param Integer[] $rightChild
     * @return Boolean
     */
    function validateBinaryTreeNodes($n, $leftChild, $rightChild) {
        $indeg = array_fill(0, $n, 0);
        for ($i = 0; $i < $n; $i++) {
            $l = $leftChild[$i];
            $r = $rightChild[$i];
            if ($l !== -1) {
                $indeg[$l]++;
                if ($indeg[$l] > 1) return false;
            }
            if ($r !== -1) {
                $indeg[$r]++;
                if ($indeg[$r] > 1) return false;
            }
        }
        $root = -1;
        for ($i = 0; $i < $n; $i++) {
            if ($indeg[$i] === 0) {
                if ($root !== -1) return false;
                $root = $i;
            }
        }
        if ($root === -1) return false;

        $visited = array_fill(0, $n, false);
        $stack = [$root];
        $visited[$root] = true;
        $count = 0;
        while (!empty($stack)) {
            $node = array_pop($stack);
            $count++;
            $l = $leftChild[$node];
            $r = $rightChild[$node];
            if ($l !== -1) {
                if ($visited[$l]) return false;
                $visited[$l] = true;
                $stack[] = $l;
            }
            if ($r !== -1) {
                if ($visited[$r]) return false;
                $visited[$r] = true;
                $stack[] = $r;
            }
        }
        return $count === $n;
    }
}
